const icon=(name,extra='')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}><path d="${paths[name==='path'?'pen':name]||paths.rect}"/></svg>`;
const NS='http://www.w3.org/2000/svg';
const STORAGE='rash-studio-project-v1';
let project,hasProjectWork=false;
try{project=parseProject(localStorage.getItem(STORAGE)||'');hasProjectWork=true;}catch{project=createProject();}
let selectedId=null,frame=0,playing=false,loop=true,tool='select',grid=true,zoom=1,inspectorTab='properties',history=[],future=[],drag=null,clipboard=null,game=null,gameSnapshot=null,runtime=null,runtimeError=null;
let saveTimer,toastTimer,raf=0,lastTick=0,frameAccumulator=0,modalKind='',previewSVG=null,searchTicket=0;
