function selected(){return project.nodes.find(n=>n.id===selectedId);}
const isMobile=()=>matchMedia('(max-width:780px), (max-width:1000px) and (pointer:coarse)').matches;
function canEdit(){if(!selected()){notify('Select a layer first.');return false;}if(selected().locked){notify('Unlock this layer before editing.');return false;}return true;}
function renderSelectionActions(){const n=selected();$('#selection-actions').hidden=!n;$('#selection-hint').hidden=!!n;$('#selection-toolbar [data-action="delete"]').disabled=!!n?.locked;$('#selection-toolbar [data-action="undo"]').disabled=!history.length;$('#selection-toolbar [data-action="redo"]').disabled=!future.length;}
function closePanels(){for(const id of ['#left-panel','#right-panel'])$(id).classList.remove('mobile-open');$('#panel-backdrop').hidden=true;$$('.mobile-nav [aria-expanded]').forEach(b=>{b.setAttribute('aria-expanded','false');b.classList.remove('active');});}
function openPanel(panel){closePanels();if(!isMobile())return;$(panel).classList.add('mobile-open');$('#panel-backdrop').hidden=false;const b=$(`.mobile-nav [aria-controls="${panel.slice(1)}"]`);b?.setAttribute('aria-expanded','true');b?.classList.add('active');}
function openInspector(tab='properties'){stopPlayback();inspectorTab=tab;renderInspector();openPanel('#right-panel');$('#inspector').scrollTop=0;}
function editTextDialog(){if(!canEdit()||selected().type!=='text')return;openModal(`${modalHeader('Edit text','Your changes apply when you choose Apply text.')}<div class="modal-body"><label class="form-label" for="edit-text-input">TEXT CONTENT</label><textarea id="edit-text-input" class="text-input" aria-label="Text content" maxlength="5000" rows="5">${esc(selected().text)}</textarea></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="apply-text">Apply text</button></div>`,'text');}

function currentNode(){return evaluateScene(project,frame).find(n=>n.id===selectedId);}
function isGame(){return project.nodes.some(n=>n.name==='player')&&project.nodes.some(n=>n.name.startsWith('energy-'));}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
const HISTORY_BYTES=20*1024*1024;
function trimHistory(){while(history.length+future.length>80 || [...history,...future].reduce((sum,item)=>sum+item.length*2,0)>HISTORY_BYTES){if(history.length)history.shift();else future.shift();}}
function checkpoint(){hasProjectWork=true;future=[];const snapshot=serializeProject(project);if(snapshot.length*2<=HISTORY_BYTES){history.push(snapshot);trimHistory();}}
function restore(text){stopPlayback();project=parseProject(text);selectedId=project.nodes.some(n=>n.id===selectedId)?selectedId:null;frame=Math.min(frame,project.duration-1);game=null;render();scheduleSave();}
function undo(){if(!history.length)return notify('You are at the beginning of your history.');const snapshot=history.pop();future.push(serializeProject(project));trimHistory();restore(snapshot);notify('Change undone');}
function redo(){if(!future.length)return notify('No changes to redo.');const snapshot=future.pop();history.push(serializeProject(project));trimHistory();restore(snapshot);notify('Change restored');}
function scheduleSave(){clearTimeout(saveTimer);$('#save-status').innerHTML='<i></i> Saving locally';saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE,serializeProject(gameSnapshot||project));$('#save-status').innerHTML='<i></i> Saved on this device';}catch{$('#save-status').textContent='Export a copy to save';notify('Device storage is unavailable. Use File → Save project for a backup.');}},300);}
function commit(){project=validateProject(project);game=null;render();scheduleSave();}
function change(fn){const before=cloneProject(project),past=history.slice(),next=future.slice(),selection=selectedId;checkpoint();try{fn();commit();return true;}catch(error){project=before;history=past;future=next;selectedId=selection;render();notify(error.message);return false;}}
function timecode(f=frame){const sec=Math.floor(f/project.fps);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}:${String(f%project.fps).padStart(2,'0')}`;}
function fitStage(){const area=$('#stage-area'),w=area.clientWidth,h=area.clientHeight;const style=getComputedStyle(area),spaceX=parseFloat(style.paddingLeft)+parseFloat(style.paddingRight),spaceY=parseFloat(style.paddingTop)+parseFloat(style.paddingBottom);const ratio=Math.min(Math.max(10,w-spaceX)/project.width,Math.max(10,h-spaceY)/project.height);const wrap=$('#stage-surround');wrap.style.width=`${project.width*ratio*zoom}px`;wrap.style.height=`${project.height*ratio*zoom}px`;$('#zoom-label').textContent=zoom===1?'Fit':`${Math.round(ratio*zoom*100)}%`;}
function renderStage(){renderScene(stage,project,frame,{selectedId:playing?null:selectedId,onSelect:(id)=>{if(tool==='select'&&!drag)selectNode(id);}});if(previewSVG)renderScene(previewSVG,project,frame);$('#stage-overlay').setAttribute('viewBox',`0 0 ${project.width} ${project.height}`);$('#render-count').textContent=`${project.nodes.filter(n=>n.visible).length} objects`;$('#frame-status').textContent=`Frame ${frame+1} of ${project.duration}`;$('#timecode').textContent=timecode();const previewTime=$('#preview-time');if(previewTime)previewTime.textContent=timecode();updatePlayhead();}
function render(){renderSelectionActions();document.title=`${project.name} · Rash Studio`;$('.project-name').textContent=project.name;$('#artboard-name').textContent=project.name;$('#artboard-size').textContent=`${project.width} × ${project.height}`;$('#fps-select').value=project.fps;renderLayers();renderInspector();renderTimeline();renderStage();fitStage();$('#selection-status').textContent=selected()?`${selected().name} · ${selected().type==='text'?'Text':'Vector shape'}`:'Select an object to start creating';$('#timeline-summary').textContent=`${project.nodes.length} layers · ${(project.duration/project.fps).toFixed(1)}s`;}
function selectNode(id){selectedId=id;renderSelectionActions();renderLayers();renderInspector();renderTimeline();renderStage();$('#selection-status').textContent=selected()?`${selected().name} · ${selected().type==='text'?'Text':'Vector shape'}`:'Select an object to start creating';}
function renderLayers(){const list=$('#layer-list');list.innerHTML=project.nodes.length?[...project.nodes].reverse().map(n=>`<div class="layer-item ${n.id===selectedId?'selected':''} ${!n.visible?'is-hidden':''} ${n.locked?'is-locked':''}" data-layer="${esc(n.id)}" tabindex="0" role="button" aria-label="Select ${esc(n.name)}" aria-pressed="${n.id===selectedId}">${icon(n.type==='path'?'pen':n.type)}<span class="layer-name" title="Select layer to edit">${esc(n.name)}</span><div class="layer-controls"><button data-layer-action="edit" data-id="${esc(n.id)}" aria-label="Edit ${esc(n.name)}" title="Edit layer">${icon('settings')}</button><button data-layer-action="visibility" data-id="${esc(n.id)}" class="${!n.visible?'is-off':''}" aria-label="${n.visible?'Hide':'Show'} ${esc(n.name)}" title="${n.visible?'Hide':'Show'} layer">${icon(n.visible?'eye':'eyeOff')}</button><button data-layer-action="lock" data-id="${esc(n.id)}" class="${n.locked?'is-locked':''}" aria-label="${n.locked?'Unlock':'Lock'} ${esc(n.name)}" title="${n.locked?'Unlock':'Lock'} layer">${icon(n.locked?'lock':'unlock')}</button></div></div>`).join(''):'<div class="blank-state">An open canvas.<br/>Choose a drawing tool to make your first mark.</div>';}
const field=(label,prop,value,unit='',min='',max='')=>`<label class="field"><span>${label}</span><input type="number" data-property="${prop}" aria-label="${({x:'X position',y:'Y position',width:'Width',height:'Height',rotation:'Rotation',fontSize:'Font size',strokeWidth:'Stroke width',rx:'Corner radius',scale:'Scale'})[prop]||label}" value="${round(value??0)}" step="${prop==='scale'?'.1':'1'}" ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''}/>${unit?`<span class="field-unit">${unit}</span>`:''}</label>`;
function renderInspector(){const box=$('#inspector');const node=selected(),n=currentNode();$$('[data-inspector]').forEach(b=>{b.classList.toggle('active',b.dataset.inspector===inspectorTab);b.setAttribute('aria-selected',String(b.dataset.inspector===inspectorTab));});
 if(inspectorTab==='motion'){if(!node){box.innerHTML=`<div class="motion-empty">${icon('diamond')}Select a layer to give it a little momentum. Add keyframes, change position, and choose how the motion feels.</div><div class="property-section"><h3>Composition timing</h3>${documentTiming()}<p class="property-note">Each keyframe records the object’s position, size, rotation, scale and opacity.</p></div>`;return;}const key=node.keyframes.find(k=>k.frame===frame);box.innerHTML=`<div class="property-section"><h3 class="selected-name">${icon(node.type)}${esc(node.name)}</h3><span class="node-kind">${node.keyframes.length} keyframes · Frame ${frame+1}</span></div><div class="property-section"><h3>Playhead</h3><div class="frame-controls"><button class="button" data-action="previous-frame" aria-label="Previous frame">‹</button><label class="field"><span>Frame</span><input id="current-frame" aria-label="Current frame" type="number" min="1" max="${project.duration}" value="${frame+1}"/></label><button class="button" data-action="next-frame" aria-label="Next frame">›</button></div></div><div class="property-section"><h3>Keyframes <span class="pill">TWEENED</span></h3><p class="property-note">Move the playhead, add a keyframe, then adjust the object. Rash fills in the motion.</p><button class="button" data-action="add-keyframe">${icon('diamond')} Add keyframe here</button><div class="keyframe-list">${node.keyframes.map(k=>`<button class="keyframe-chip ${k.frame===frame?'active':''}" data-seek="${k.frame}" aria-label="Go to keyframe ${k.frame+1}">◇ ${k.frame+1}</button>`).join('')}</div></div><div class="property-section"><h3>Easing into this frame</h3><select class="easing-select" id="easing-select" aria-label="Keyframe easing" ${key?'':'disabled'}>${[['linear','Linear'],['easeIn','Ease in'],['easeOut','Ease out'],['easeInOut','Ease in and out'],['step','Hold']].map(([v,l])=>`<option value="${v}" ${key?.easing===v?'selected':''}>${l}</option>`).join('')}</select><p class="property-note">${key?'Controls the transition into the selected keyframe.':'Select an existing keyframe to edit its easing.'}</p>${key?'<button class="button danger-button" data-action="remove-keyframe">Remove this keyframe</button>':''}</div><div class="property-section"><h3>Composition timing</h3>${documentTiming()}</div>`;applyInspectorLocks(node);return;}
 if(!node){box.innerHTML=`<div class="property-section"><h3>Composition <span class="pill">SVG NATIVE</span></h3><div class="document-preview" style="aspect-ratio:${project.width}/${project.height}"><span>${project.width} × ${project.height}</span></div><label class="field full-field"><span>${icon('folder')}</span><input data-document="name" type="text" aria-label="Project name" maxlength="120" value="${esc(project.name)}" /></label><div class="field-grid" style="margin-top:8px"><label class="field"><span>W</span><input data-document="width" aria-label="Canvas width" type="number" value="${project.width}" min="16" max="4096"/></label><label class="field"><span>H</span><input data-document="height" aria-label="Canvas height" type="number" value="${project.height}" min="16" max="4096"/></label></div><button class="button" data-action="resize">${icon('resize')} Resize composition</button></div><div class="property-section"><h3>Background</h3><label class="field color-field"><input data-document="background" aria-label="Background color" type="color" value="${/^#[a-f\d]{6}$/i.test(project.background)?project.background:'#111522'}"/><span class="color-value">${esc(project.background.toUpperCase())}</span><span class="field-unit" style="margin-left:auto">100%</span></label></div><div class="property-section"><h3>Playback</h3>${documentTiming()}<label class="property-toggle">Loop animation <input id="loop-inspector" type="checkbox" ${loop?'checked':''}/></label></div><div class="property-section"><h3>Ready for the web</h3><p class="property-note">A responsive, interactive composition. Export once and bring it to any website.</p><button class="button" data-action="share">${icon('code')} Get embed code</button></div>`;return;}
 box.innerHTML=`<div class="property-section"><h3 class="selected-name">${icon(node.type==='path'?'pen':node.type)}<button data-action="rename-layer" aria-label="Rename layer" title="Rename layer"><span>${esc(node.name)}</span><small class="rename-label">Rename</small></button></h3><span class="node-kind">${node.type==='text'?'Editable text':'Vector shape'} · ${node.keyframes.length?'Animated':'Static'}</span></div><div class="property-section"><h3>Transform <span class="section-caption">${frame?'FRAME '+(frame+1):'ABSOLUTE'}</span></h3><div class="alignment-buttons">${[['left','alignLeft'],['center','alignCenter'],['right','alignRight'],['top','alignTop'],['middle','alignMiddle'],['bottom','alignBottom']].map(([a,i])=>`<button data-align="${a}" title="Align ${a} to stage" aria-label="Align ${a} to stage">${icon(i)}</button>`).join('')}</div><div class="field-grid">${field('X','x',n.x)}${field('Y','y',n.y)}${field('W','width',n.width,'',1,10000)}${field('H','height',n.height,'',1,10000)}${field('∠','rotation',n.rotation,'°')}${field('↗','scale',n.scale??1,'×',.001,100)}</div></div>${node.type==='text'?`<div class="property-section"><h3>Typography</h3><button class="button" data-action="edit-text" aria-label="Edit text content">Edit text content</button><textarea data-property="text" aria-label="Text content" class="font-textarea" maxlength="5000">${esc(node.text)}</textarea><div class="field-grid" style="margin-top:8px">${field('Aa','fontSize',n.fontSize,'px',1,1000)}<label class="field"><select data-property="fontWeight" aria-label="Font weight">${[400,500,600,700,800,900].map(w=>`<option ${node.fontWeight===w?'selected':''} value="${w}">${w}</option>`).join('')}</select></label></div></div>`:''}<div class="property-section"><h3>Appearance</h3><div class="field-label">Fill</div><label class="field color-field"><input type="color" data-property="fill" aria-label="Fill color" value="${/^#[a-f\d]{6}$/i.test(node.fill)?node.fill:'#ff6b35'}"/><span class="color-value">${esc(node.fill.toUpperCase())}</span><button style="margin-left:auto;font-size:8px;color:#92a07f" data-action="toggle-fill" title="Toggle fill">${node.fill==='none'?'Enable':'None'}</button></label><div class="field-label">Stroke</div><div class="field-grid"><label class="field color-field"><input type="color" data-property="stroke" aria-label="Stroke color" value="${/^#[a-f\d]{6}$/i.test(node.stroke)?node.stroke:'#555555'}"/><span class="color-value">${node.stroke==='none'?'NONE':esc(node.stroke.toUpperCase())}</span></label>${field('↔','strokeWidth',node.strokeWidth,'',0,100)}</div><div class="field-label">Opacity</div><div class="slider-field"><input data-property="opacity" type="range" min="0" max="1" step=".01" value="${n.opacity}" aria-label="Opacity"/><span>${Math.round(n.opacity*100)}%</span></div>${node.type==='rect'?`<div class="field-label">Corner radius</div>${field('⌜','rx',node.rx??0,'px',0,1000)}`:''}</div><div class="property-section"><h3>Arrange</h3><div class="field-grid"><button class="button" data-action="bring-forward">${icon('arrowUp')} Forward</button><button class="button" data-action="send-backward">${icon('arrowDown')} Backward</button></div><div class="field-grid"><button class="button" data-action="duplicate">${icon('copy')} Duplicate</button><button class="button danger-button" data-action="delete">${icon('trash')} Delete</button></div><button class="button" data-action="motion-inspector">${icon('diamond')} Animate this layer</button></div>`;applyInspectorLocks(node);}
function applyInspectorLocks(node){if(!node?.locked)return;$('#inspector').insertAdjacentHTML('afterbegin',`<div class="locked-notice"><span>${icon('lock')} This layer is locked</span><button class="button" data-action="unlock-layer">Unlock layer</button></div>`);$$('#inspector [data-property],#inspector [data-align],#inspector #easing-select,#inspector [data-action]').forEach(b=>{if(['rename-layer','edit-text','toggle-fill','bring-forward','send-backward','delete','add-keyframe','remove-keyframe'].includes(b.dataset.action)||b.matches('[data-property],[data-align],#easing-select'))b.disabled=true;});}
function setProjectFPS(value){const previous=project.fps,next=clamp(Math.round(Number(value)||30),1,120),ratio=next/previous;project.fps=next;project.duration=Math.max(1,Math.round(project.duration*ratio));frame=Math.min(project.duration-1,Math.round(frame*ratio));for(const node of project.nodes)node.keyframes=node.keyframes.map(k=>({...k,frame:Math.min(project.duration-1,Math.round(k.frame*ratio))}));}
function documentTiming(){return `<div class="field-grid"><label class="field"><span>FPS</span><input type="number" data-document="fps" aria-label="Playback frames per second" value="${project.fps}" min="1" max="120"/></label><label class="field"><span>◷</span><input type="number" data-document="seconds" aria-label="Duration in seconds" value="${round(project.duration/project.fps)}" min=".1" max="600" step=".1"/><span class="field-unit">s</span></label></div>`;}
function setNodeProperty(prop,value){const node=selected();if(!node||node.locked)return;const anim=['x','y','width','height','rotation','opacity','scale'];if(anim.includes(prop)&&frame>0){const key=addKeyframe(project,node.id,frame);key[prop]=value;}else{node[prop]=value;const key=node.keyframes.find(k=>k.frame===0);if(key&&anim.includes(prop))key[prop]=value;}if(prop==='stroke'&&node.strokeWidth===0)node.strokeWidth=1;}
function renderTimeline(){const order=[...project.nodes].reverse();$('#timeline-labels').innerHTML=order.map(n=>`<div class="track-label ${n.id===selectedId?'selected':''}" data-layer="${esc(n.id)}" tabindex="0" role="button" aria-label="Select timeline ${esc(n.name)}">${icon(n.type==='path'?'pen':n.type)}<span>${esc(n.name)}</span><i class="track-dot"></i></div>`).join('');const rowHeight=isMobile()?36:29,headerHeight=isMobile()?30:26;const svg=$('#timeline-svg'),width=Math.max(620,$('#tracks-scroll').clientWidth),height=Math.max(headerHeight+order.length*rowHeight,130);svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);svg.style.width=`${width}px`;const duration=project.duration/project.fps,step=duration>25?5:duration>12?2:1;let markup=`<rect width="${width}" height="${height}" fill="#fafbf5"/><rect width="${width}" height="${headerHeight}" fill="#f7f9ef"/>`;for(let s=0;s<duration;s+=step){const x=12+s/duration*(width-24);markup+=`<path d="M${x} 23V${height}" stroke="#e9edde" stroke-width="1"/><text x="${x+3}" y="16" fill="#a6b392" font-size="8" font-family="Inter,Arial">${s===0?'00:00':s+'s'}</text>`;for(let m=1;m<4;m++){const xx=x+m*step/4/duration*(width-24);if(xx<width-12)markup+=`<path d="M${xx} 21v4" stroke="#c7d0b8"/>`;}}order.forEach((n,i)=>{const y=headerHeight+i*rowHeight,color=n.id===selectedId?'#f6a36f':n.type==='text'?'#d7dfb8':n.type==='ellipse'?'#d5dfc9':'#dfdabb';markup+=`<path d="M0 ${y+rowHeight}H${width}" stroke="#edf0e3"/>${n.id===selectedId?`<rect x="0" y="${y}" width="${width}" height="${rowHeight}" fill="#f9f0e5"/>`:''}<rect x="13" y="${y+8}" width="${width-28}" height="13" rx="3" fill="${color}" opacity="${n.visible?'.6':'.2'}"/>`;n.keyframes.forEach(k=>{const x=12+k.frame/(project.duration-1||1)*(width-24);markup+=`<path data-keyframe="${k.frame}" data-node="${esc(n.id)}" d="m${x} ${y+9} 5 5-5 5-5-5Z" fill="${n.id===selectedId?'#d97242':'#91a375'}" stroke="#fff" stroke-width=".65"/>`;});});markup+=`<g id="playhead" pointer-events="none"><path d="M0 24V${height}" stroke="#dc7048" stroke-width="1"/><path d="M-5 1H5V17L0 22-5 17Z" fill="#f16b43"/></g>`;svg.innerHTML=markup;updatePlayhead();}
function updatePlayhead(){const head=$('#playhead'),svg=$('#timeline-svg');if(head){const width=Number(svg.getAttribute('width'))||620;head.setAttribute('transform',`translate(${12+frame/(project.duration-1||1)*(width-24)},0)`);}}
function seek(value){frame=clamp(Math.round(value),0,project.duration-1);renderStage();renderInspector();}
function stopPlayback(){playing=false;cancelAnimationFrame(raf);if(gameSnapshot){project=gameSnapshot;gameSnapshot=null;game=null;render();}$('#play-button').innerHTML=icon('play');$('#play-button').setAttribute('aria-label','Play animation');const b=$('#preview-play');if(b)b.innerHTML=`${icon('play')} Play`;}
function togglePlayback(){if(playing){stopPlayback();return;}if(frame>=project.duration-1)frame=0;if(isGame()){if(!game){gameSnapshot=cloneProject(project);game=createGame(project);}if(game.status==='won'||game.status==='lost')game.reset();}playing=true;lastTick=performance.now();frameAccumulator=0;$('#play-button').innerHTML=icon('pause');$('#play-button').setAttribute('aria-label','Pause animation');const b=$('#preview-play');if(b)b.innerHTML=`${icon('pause')} Pause`;raf=requestAnimationFrame(tick);}
function tick(now){if(!playing)return;const dt=Math.min((now-lastTick)/1000,.1);lastTick=now;if(game&&isGame()){game.step(dt,gameInput);if(game.status==='won'||game.status==='lost'){const status=game.status,score=game.score;stopPlayback();notify(status==='won'?`All signals collected. Score ${score}.`:`Signal lost. Score ${score}. Press play to try again.`);}}else{frameAccumulator+=dt*project.fps;const advance=Math.floor(frameAccumulator);frameAccumulator-=advance;frame+=advance;if(frame>=project.duration){if(loop)frame%=project.duration;else{frame=project.duration-1;stopPlayback();}}}renderStage();if(playing)raf=requestAnimationFrame(tick);}
function setTool(value){tool=value;closePanels();$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));stage.style.cursor=tool==='select'?'default':tool==='hand'?'grab':'crosshair';$('#selection-status').textContent=tool==='select'?'Select and drag an object':tool==='hand'?'Drag to pan the stage':tool==='text'?'Click the stage to add text':`Drag on the stage to draw a ${tool==='path'?'freehand path':tool}`;}
function pointFromEvent(event,svg=stage){const r=svg.getBoundingClientRect();return {x:(event.clientX-r.left)/r.width*project.width,y:(event.clientY-r.top)/r.height*project.height};}
function addShape(type){stopPlayback();change(()=>{const n=addNode(project,type);if(type==='text'&&project.background!=='#111522')n.fill='#27322b';if(type==='path'){n.width=160;n.height=100;n.pathWidth=160;n.pathHeight=100;n.fill='none';n.stroke='#f16b43';n.strokeWidth=3;n.d='M0 80 Q40 -20 80 50 T160 20';}selectedId=n.id;});setTool('select');}
function deleteSelected(){if(!canEdit())return;const name=selected().name;change(()=>{project.nodes=project.nodes.filter(n=>n.id!==selectedId);selectedId=null;});notify(`${name} deleted. Tap Undo to restore it.`);}
function duplicate(){const n=selected();if(!n)return notify('Select a layer to duplicate.');change(()=>{const copy=addNode(project,n.type),id=copy.id;Object.assign(copy,structuredClone(n),{id,name:n.name+' copy',x:n.x+24,y:n.y+24,locked:false});copy.keyframes=copy.keyframes.map(k=>({...k,...(Number.isFinite(k.x)?{x:k.x+24}:{}),...(Number.isFinite(k.y)?{y:k.y+24}:{})}));selectedId=copy.id;});}
function addCurrentKeyframe(){if(!canEdit())return;change(()=>addKeyframe(project,selectedId,frame));notify(`Keyframe added at frame ${frame+1}`);}
function reorder(direction){if(!canEdit())return;const i=project.nodes.findIndex(n=>n.id===selectedId),j=clamp(i+direction,0,project.nodes.length-1);if(i===j)return;change(()=>{const n=project.nodes.splice(i,1)[0];project.nodes.splice(j,0,n);});}
function download(blob,filename){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function saveProject(){download(new Blob([serializeProject(project)],{type:'application/json'}),project.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'.rash.json');scheduleSave();notify('Project downloaded. Keep this file to edit again.');}
function modalHeader(title,subtitle=''){return `<div class="modal-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div>`;}
function openModal(content,kind=''){if(playing&&kind!=='preview')stopPlayback();if(modalKind==='script'&&$('#script-input'))persistScriptDraft();closeMenu();closePanels();modalKind=kind;$('#modal-content').innerHTML=content;const dialog=$('#modal');if(!dialog.open)dialog.showModal();}
function persistScriptDraft(){const source=$('#script-input')?.value;if(source!==undefined&&source!==project.script)change(()=>project.script=source);}
function closeModal(){if(modalKind==='script')persistScriptDraft();if(modalKind==='preview'){previewSVG=null;stopPlayback();}$('#modal').close();modalKind='';}
const templateSVG=id=>sceneToSVG(createProject(id,id==='social'?'story':'web'),0);
let wizardTemplate='orbit',wizardPreset='web',wizardReplacementRequired=false;
function openNewProject(template){stopPlayback();wizardTemplate=template||'orbit';wizardPreset=template==='social'?'story':'web';newProjectDialog();}
function newProjectDialog(){wizardReplacementRequired=hasProjectWork;openModal(`${modalHeader('Every great idea starts somewhere.','Choose a canvas and a starting point. This browser keeps one current composition. Download a backup before replacing your work.')}<div class="modal-body"><div class="form-row"><div><label class="form-label" for="new-name">COMPOSITION NAME</label><input class="text-input" id="new-name" value="${esc(templates.find(t=>t.id===wizardTemplate)?.name.split(' / ')[0]||'Untitled project')}" maxlength="120"/></div><div><label class="form-label" for="new-fps">FRAME RATE</label><select id="new-fps" class="text-input"><option value="24">24 fps · Cinematic</option><option value="30" selected>30 fps · Balanced</option><option value="60">60 fps · Smooth</option></select></div></div><section><h3>Make room for your idea</h3><div class="preset-grid">${presets.map(p=>`<button class="preset-choice ${p.id===wizardPreset?'selected':''}" data-wizard-preset="${p.id}" aria-pressed="${p.id===wizardPreset}"><span class="preset-preview" style="width:${p.width/p.height>=1?26:Math.round(22*p.width/p.height)}px;height:${p.width/p.height>=1?Math.round(26*p.height/p.width):22}px"></span><strong>${esc(p.name)}</strong><small>${p.width} × ${p.height}</small></button>`).join('')}</div></section><section><h3>A little inspiration to get moving</h3><div class="template-grid">${templates.map(t=>`<button class="template-choice ${t.id===wizardTemplate?'selected':''}" data-wizard-template="${t.id}" aria-pressed="${t.id===wizardTemplate}"><div class="template-art">${templateSVG(t.id)}</div><div class="template-caption"><strong>${esc(t.name)}</strong><p>${esc(t.description)}</p></div></button>`).join('')}</div></section>${wizardReplacementRequired?'<label class="replace-consent"><input id="replace-project" type="checkbox"/> Replace the current composition and its device autosave. I have saved any work I need.</label>':''}</div><div class="modal-footer"><button class="button" data-action="save">Download current project</button><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="create-project">Create composition ${icon('plus')}</button></div>`,'new');}
function createNew(){if(wizardReplacementRequired&&!$('#replace-project')?.checked){$('#replace-project')?.focus();return notify('Download a backup, then confirm replacement of the current composition.');}const name=$('#new-name').value.trim()||'Untitled project',fps=Number($('#new-fps').value);checkpoint();project=createProject(wizardTemplate,wizardPreset);project.name=name;for(const n of project.nodes)for(const k of n.keyframes)k.frame=Math.round(k.frame*fps/project.fps);project.fps=fps;project.duration=fps*8;frame=0;selectedId=null;zoom=1;game=null;closeModal();commit();notify(isGame()?'Orbit collector is ready. Press Play and use arrow keys or touch.':'A fresh composition. Make it yours.');}
function renameDialog(isLayer=false){const node=selected();if(isLayer&&!canEdit())return;openModal(`${modalHeader(isLayer?'Name this layer':'Name this composition')}<div class="modal-body"><label class="form-label" for="rename-input">${isLayer?'LAYER':'COMPOSITION'} NAME</label><input id="rename-input" class="text-input" value="${esc(isLayer?node.name:project.name)}" maxlength="${isLayer?100:120}" /></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="${isLayer?'confirm-layer-name':'confirm-project-name'}">Save name</button></div>`,'rename');setTimeout(()=>{$('#rename-input')?.focus();$('#rename-input')?.select();},0);}
function resizeDialog(){openModal(`${modalHeader('A canvas for every screen.','Resize the stage. Scale your artwork proportionally, or keep its current dimensions.')}<div class="modal-body"><label class="form-label" for="resize-preset">SIZE PRESET</label><select id="resize-preset" class="text-input"><option value="custom">Custom size</option>${presets.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.width} × ${p.height}</option>`).join('')}</select><div class="form-row" style="margin-top:18px"><div><label class="form-label" for="resize-width">WIDTH</label><input class="text-input" id="resize-width" type="number" min="16" max="4096" value="${project.width}"/></div><div><label class="form-label" for="resize-height">HEIGHT</label><input class="text-input" id="resize-height" type="number" min="16" max="4096" value="${project.height}"/></div></div><label class="property-toggle">Scale artwork to fit <input id="resize-scale" type="checkbox" checked/></label><p class="form-hint">Vector artwork stays sharp at any size. Canvas limits are 16 to 4096 pixels per side.</p></div><div class="modal-footer"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-resize">Resize composition</button></div>`,'resize');}
function applyResize(){const w=clamp(Number($('#resize-width').value)||1280,16,4096),h=clamp(Number($('#resize-height').value)||720,16,4096),scale=$('#resize-scale').checked;checkpoint();if(scale){const sx=w/project.width,sy=h/project.height,s=Math.min(sx,sy);for(const n of project.nodes){n.x*=sx;n.y*=sy;n.width*=sx;n.height*=sy;n.fontSize*=s;n.strokeWidth*=s;n.rx*=s;for(const k of n.keyframes){for(const p of ['x','width'])if(Number.isFinite(k[p]))k[p]*=sx;for(const p of ['y','height'])if(Number.isFinite(k[p]))k[p]*=sy;}}}project.width=w;project.height=h;zoom=1;closeModal();commit();}
const formats=[['png','PNG','A still image at full canvas size','IMAGE'],['svg','SVG','Crisp animated vectors','VECTOR'],['gif','GIF','An animation that goes anywhere','LOOP'],['mp4','MP4','Video for social and presentations','VIDEO'],['pdf','PDF','A first-frame snapshot, ready for print','PRINT'],['html','HTML','A self-contained animated document','WEB'],['json','Project','An editable Rash project file','SOURCE']];
let chosenFormat='svg',exporting=false;
function exportDialog(){chosenFormat='svg';openModal(`${modalHeader('Let your ideas out.','Export your composition, or embed an interactive player on your own site.')}<div class="modal-body"><div class="format-grid">${formats.map(([id,name,description,tag])=>`<button class="format-choice ${id===chosenFormat?'selected':''}" data-format="${id}" aria-pressed="${id===chosenFormat}"><strong>${name}<small>${tag}</small></strong><p>${description}</p></button>`).join('')}</div><div class="export-summary"><span>${esc(project.name)}</span><span>${project.width} × ${project.height}</span><span>${project.fps} fps</span><span>${(project.duration/project.fps).toFixed(1)} seconds</span></div><p class="code-info" id="format-note">SVG preserves your vector artwork and animation. No player installation required.</p><p id="export-progress" class="export-progress" role="status"></p></div><div class="modal-footer"><button class="button" data-action="share">${icon('code')} Embed instead</button><button class="button primary" id="download-export" data-action="download-export">${icon('export')} Export SVG</button></div>`,'export');}
async function doExport(){if(exporting)return;exporting=true;const b=$('#download-export'),status=$('#export-progress');b.disabled=true;status.classList.remove('error');status.textContent='Preparing your composition…';const snapshot=cloneProject(project);try{const result=await exportProject(snapshot,chosenFormat,{onProgress:value=>{if(status.isConnected)status.textContent=typeof value==='string'?value:`Rendering ${Math.round(Number(value)*100)}%…`;}});download(result.blob,result.filename);if(status.isConnected)status.textContent=`${result.filename} is ready. Your download has started.`;notify(`Exported ${chosenFormat.toUpperCase()}`);}catch(e){if(status.isConnected){status.classList.add('error');status.textContent=e.message||'Export was not available in this browser.';}}finally{exporting=false;if(b.isConnected)b.disabled=false;}}
function shareDialog(){let code;try{code=embedCode(project,{baseURL:new URL('./',location.href).href});}catch(e){code=`Embed generation failed: ${e.message}`;}openModal(`${modalHeader('Made here. Played everywhere.','Add Rash to your website with a self contained, isolated player.')}<div class="modal-body"><label class="form-label" for="embed-code">JAVASCRIPT EMBED</label><textarea id="embed-code" class="embed-code" rows="9" readonly spellcheck="false">${esc(code)}</textarea><p class="code-info">Paste into an HTML page. The player scales to its container and keeps scene scripts isolated from the host page. Your project data is included in the snippet.</p><div class="export-summary"><span>Responsive SVG</span><span>Browser playback</span><span>No account required</span></div><button class="text-link" data-action="preview">Preview this composition ↗</button></div><div class="modal-footer"><span class="footer-note">Need a file? Export HTML for a standalone player.</span><button class="button" data-action="download-embed">Download snippet</button><button class="button primary" data-action="copy-embed">${icon('copy')} Copy embed code</button></div>`,'share');}
function previewDialog(){stopPlayback();openModal(`${modalHeader('A little motion goes a long way.',isGame()?'Use arrow keys, WASD or touch the stage. Collect the green signals.':'Your composition, without the editing tools.')}<div class="preview-shell"><svg id="preview-stage" xmlns="${NS}" aria-label="Composition preview"></svg></div><div class="modal-footer preview-footer"><span class="preview-time" id="preview-time">${timecode()}</span><div style="display:flex;gap:8px"><button class="button" data-action="reset-preview">${icon('loop')} Restart</button><button class="button primary" id="preview-play" data-action="play">${icon('play')} Play</button></div></div>`,'preview');previewSVG=$('#preview-stage');renderStage();if(isGame()){previewSVG.style.touchAction='none';previewSVG.addEventListener('pointerdown',e=>{gameInput.target=pointFromEvent(e,previewSVG);});previewSVG.addEventListener('pointermove',e=>{if(e.buttons||e.pointerType==='touch')gameInput.target=pointFromEvent(e,previewSVG);});}togglePlayback();}
const scriptSamples={hello:'// The stage is yours.\ntrace("Hello, Rash.");\n',animation:'// Timeline controls\ntrace("Playing the composition");\ngotoAndPlay(1);\n',object:'// Refer to a layer by its exact name or id.\n// Example: getNode("Orbit / orange").x = 650;\ntrace("Open the compatibility guide for supported syntax.");\n'};
function scriptDialog(){stopPlayback();openModal(`${modalHeader('A little code. A lot of possibility.','RashScript runs in a bounded Rust and WebAssembly worker. ActionScript compatibility is an explicitly documented subset.')}<div class="modal-body"><div class="script-toolbar"><span class="pill" id="script-engine">${runtime?esc(runtime.kind):'INITIALIZING'}</span><select id="script-sample" class="text-input" aria-label="Script example"><option value="">Examples…</option><option value="hello">Hello, Rash</option><option value="animation">Timeline control</option><option value="object">Object property guide</option></select></div><textarea id="script-input" class="script-input" spellcheck="false" aria-label="ActionScript editor" maxlength="50000">${esc(project.script)}</textarea><div class="script-output" id="script-output" role="log" aria-live="polite">${runtimeError?esc(runtimeError):'Ready. Run your script to see trace output here.'}</div><p class="code-info">No eval, DOM access or network access. Unsupported language features are rejected. <a href="https://github.com/ruvnet/Rash/blob/main/docs/compatibility.md" target="_blank" rel="noopener noreferrer" class="text-link">Compatibility guide ↗</a></p></div><div class="modal-footer"><span class="footer-note">Script source is saved with your project.</span><button class="button" data-action="save-script">Save script</button><button class="button primary" id="run-script" data-action="run-script">${icon('play')} Run script</button></div>`,'script');}
async function runScript(){
 const output=$('#script-output'),button=$('#run-script'),source=$('#script-input').value;
 project.script=source;const original=project,candidate=cloneProject(project);scheduleSave();output.textContent='Running…';button.disabled=true;
 try{
  if(!runtime)runtime=await createRuntime();
  const result=await runtime.run(source,{nodes:candidate.nodes,frame,totalFrames:candidate.duration,fps:candidate.fps,width:candidate.width,height:candidate.height});
  if(result.error)throw new Error(result.error);
  if(project!==original)throw new Error('The project changed during script execution. Run the script again.');
  let requestedPlay,requestedFrame=frame,changed=false;
  for(const c of result.commands||[]){
   const type=c.type||c.kind||c.op;
   if(type==='set'){const n=candidate.nodes.find(n=>n.id===c.id||n.name===c.id);if(n&&['x','y','width','height','rotation','opacity','scale','visible','text','fill','stroke','strokeWidth','fontSize'].includes(c.property)){n[c.property]=c.value;changed=true;}}
   if(type==='play')requestedPlay=true;
   if(type==='stop')requestedPlay=false;
   if(type==='goto'){requestedFrame=c.frame;requestedPlay=!!c.play;}
  }
  const validated=validateProject(candidate);
  if(changed)checkpoint();project=validated;frame=clamp(Math.round(requestedFrame),0,project.duration-1);render();scheduleSave();
  if(requestedPlay===true&&!playing)togglePlayback();else if(requestedPlay===false)stopPlayback();
  output.textContent=(result.logs||result.trace||[]).map(x=>typeof x==='string'?x:JSON.stringify(x)).join('\n')||'Completed without trace output.';
 }catch(e){output.textContent=`Error: ${e.message}`;}finally{button.disabled=false;}
}
function helpDialog(){const keys=[['Select tool','V'],['Draw rectangle','R'],['Draw ellipse','O'],['Draw text','T'],['Draw freehand path','P'],['Pan stage','H'],['Play / pause','Space'],['Add keyframe','K'],['Undo','Ctrl Z'],['Redo','Ctrl Shift Z'],['Duplicate','Ctrl D'],['Save project','Ctrl S'],['Command palette','Ctrl K'],['Delete layer','Delete'],['Nudge selection','Arrow keys'],['Large nudge','Shift + Arrow']];openModal(`${modalHeader('Find your flow.','A familiar stage. A new kind of creative freedom.')}<div class="modal-body"><div class="help-callout touch-help"><strong>Editing on a phone or tablet</strong><br/>Tap an object, then use Edit, Duplicate or Delete above the canvas. In Edit, change its name, text, size, position and appearance. Use Layers to reach hidden or locked objects, and Motion to set a frame and add or remove keyframes. Undo and Redo remain above the canvas. More contains open, save, scripts and the complete menu.</div><div class="help-grid">${keys.map(([name,key])=>`<div class="shortcut"><span>${name}</span><kbd>${key}</kbd></div>`).join('')}</div><div class="help-callout"><strong>Your first animation, in three moves.</strong><br/>1. Draw an object and add a keyframe at frame 1.<br/>2. Move the orange playhead, then drag the object somewhere new.<br/>3. Press Space. You just made an idea move.</div><div class="help-links"><a href="https://github.com/ruvnet/Rash" target="_blank" rel="noopener noreferrer">Source and documentation ↗</a><a href="https://github.com/ruvnet/Rash/blob/main/docs/compatibility.md" target="_blank" rel="noopener noreferrer">ActionScript compatibility ↗</a><a href="./legacy.html" target="_blank" rel="noopener noreferrer">Open legacy SWF player ↗</a><button class="text-link" data-action="resources">Explore rash:// resources ↗</button></div><p class="code-info">Use ⌘ in place of Ctrl on a Mac. Projects autosave in this browser. Export a project file to make a durable backup.</p></div><div class="modal-footer"><button class="button" data-action="new-project">Start from a template</button><button class="button primary" data-action="close-modal">Got it. Let’s make something.</button></div>`,'help');}
const commands=[['New composition','new-project','Ctrl N','plus'],['Browse templates','templates','','grid'],['Export composition','export','','export'],['Get embed code','share','','code'],['Preview animation','preview','','play'],['Save project','save','Ctrl S','save'],['Import project','import','','folder'],['Add rectangle','add-rect','R','rect'],['Add ellipse','add-ellipse','O','ellipse'],['Add text','add-text','T','text'],['Add keyframe','add-keyframe','K','diamond'],['Actions script editor','script','','code'],['Undo','undo','Ctrl Z','undo'],['Redo','redo','Ctrl Shift Z','redo'],['Resize composition','resize','','resize'],['Open rash:// resource','resources','','search'],['Keyboard shortcuts','help','?','help']];
function commandDialog(){openModal(`<div class="command-search">${icon('search')}<input id="command-input" aria-label="Search commands" placeholder="What would you like to do?" autocomplete="off"/><button class="icon-button" data-action="close-modal" aria-label="Close command palette">×</button></div><div class="command-list" id="command-list"></div>`,'commands');filterCommands('');setTimeout(()=>$('#command-input')?.focus(),0);}
function filterCommands(q){$('#command-list').innerHTML=commands.filter(c=>c[0].toLowerCase().includes(q.toLowerCase())).map(([label,action,key,i])=>`<button data-command="${action}">${icon(i)}${label}${key?`<kbd>${key}</kbd>`:''}</button>`).join('')||'<div class="blank-state">No matching commands.</div>';}
function projectInfo(){openModal(`${modalHeader('A small file. A big idea.','Your composition is a portable, inspectable scene document.')}<div class="modal-body"><dl class="project-info-list"><dt>Name</dt><dd>${esc(project.name)}</dd><dt>Canvas</dt><dd>${project.width} × ${project.height} pixels</dd><dt>Timeline</dt><dd>${project.duration} frames · ${project.fps} fps</dd><dt>Layers</dt><dd>${project.nodes.length} objects · ${project.nodes.reduce((n,o)=>n+o.keyframes.length,0)} keyframes</dd><dt>Document size</dt><dd>${(new Blob([serializeProject(project)]).size/1024).toFixed(1)} KB</dd><dt>Runtime</dt><dd>${esc(runtime?.kind||runtimeError||'Initializing')}</dd><dt>Address</dt><dd>rash://project/${esc(project.id)}</dd><dt>Storage</dt><dd>Autosaved on this browser. Download a project copy for backup.</dd></dl></div><div class="modal-footer"><button class="button" data-action="resources">Browse resources</button><button class="button primary" data-action="save">Download project</button></div>`,'info');}
const resources=createResourceRegistry({getProject:()=>project,templates,controls:{play:()=>{if(!playing)togglePlayback();},pause:stopPlayback,seek,select:selectNode}});
function resourceDialog(){openModal(`${modalHeader('A canvas you can address.','Local resources use rash:// addresses. Opening a resource never makes a network request.')}<div class="modal-body"><label class="form-label" for="resource-uri">RESOURCE ADDRESS</label><input id="resource-uri" class="text-input" value="rash://project/current"/><div style="display:flex;justify-content:flex-end;margin:10px 0"><button class="button" data-action="resolve-resource">Open resource</button></div><pre id="resource-result" class="script-output">${esc(JSON.stringify({name:project.name,width:project.width,height:project.height,layers:project.nodes.length},null,2))}</pre><h3 style="margin-top:18px">Available resources</h3><div class="keyframe-list">${resources.list().filter(x=>!x.includes('/node/')).map(uri=>`<button class="keyframe-chip" data-resource="${esc(uri)}">${esc(uri)}</button>`).join('')}</div></div><div class="modal-footer"><button class="button primary" data-action="close-modal">Back to the canvas</button></div>`,'resources');}
function resolveResource(){try{const result=resources.resolve($('#resource-uri').value);$('#resource-result').textContent=JSON.stringify(result.value,null,2);}catch(e){$('#resource-result').textContent=e.message;}}
async function renderLibrary(query=''){const ticket=++searchTicket;const result=await searchTemplates(query,templates);if(ticket!==searchTicket)return;const matches=result.results.map(r=>templates.find(t=>t.id===r.id)).filter(Boolean);$('#template-library').innerHTML=matches.map(t=>`<button data-template="${t.id}" title="Create from ${esc(t.name)}"><span class="template-mini">${templateSVG(t.id)}</span><span><strong>${esc(t.name)}</strong><small>${esc(t.tags.join(' · '))}</small></span></button>`).join('')||'<p class="blank-state">No matching templates. Try “social” or “game”.</p>';$('#template-library').setAttribute('data-search-backend',result.backend);}
function mobileMoreDialog(){openModal(`${modalHeader('Studio menu','All your tools, without a keyboard.')}<div class="mobile-menu-list">${[['undo','Undo'],['redo','Redo'],['new-project','New composition'],['import','Open project'],['save','Download project'],['resize','Resize composition'],['share','Get embed code'],['export','Export composition'],['script','Actions script editor'],['resources','Browse rash:// resources'],['commands','Search all commands'],['legacy','Open legacy SWF player'],['help','Help and shortcuts']].map(([action,label])=>`<button data-action="${action}" ${action==='undo'&&!history.length||action==='redo'&&!future.length?'disabled':''}>${label}</button>`).join('')}</div>`,'more');}
function closeMenu(){$('#menu').hidden=true;}
function openMenu(type,anchor){const menus={file:[['New composition','new-project','Ctrl N'],['Templates','templates'],['Open project…','import'],['Open legacy SWF','legacy'],['Save project','save','Ctrl S'],null,['Export…','export'],['Embed…','share'],['Project details','project-info']],edit:[['Undo','undo','Ctrl Z'],['Redo','redo','Ctrl Shift Z'],null,['Duplicate layer','duplicate','Ctrl D'],['Rename layer','rename-layer'],['Delete layer','delete','Delete'],null,['Bring forward','bring-forward'],['Send backward','send-backward']],view:[['Preview','preview'],['Fit stage','zoom-fit'],['Toggle grid','grid'],['Expand timeline','timeline-size'],['Actions script editor','script'],['Command palette','commands','Ctrl K']]};const menu=$('#menu');menu.innerHTML=(menus[type]||[]).map(item=>item?`<button class="menu-item" data-action="${item[1]}">${item[0]}${item[2]?`<kbd>${item[2]}</kbd>`:''}</button>`:'<div class="menu-divider"></div>').join('');const r=anchor.getBoundingClientRect();menu.style.left=`${Math.min(r.left,innerWidth-215)}px`;menu.style.top=`${r.bottom+8}px`;menu.hidden=false;}
