 const shape=event.target.closest('[data-shape]');if(shape){addShape(shape.dataset.shape);return;}
 const template=event.target.closest('[data-template]');if(template){openNewProject(template.dataset.template);return;}
 const wp=event.target.closest('[data-wizard-preset]');if(wp){wizardPreset=wp.dataset.wizardPreset;$$('[data-wizard-preset]').forEach(b=>{b.classList.toggle('selected',b===wp);b.setAttribute('aria-pressed',String(b===wp));});return;}
