 const format=event.target.closest('[data-format]');if(format){chosenFormat=format.dataset.format;$$('[data-format]').forEach(b=>{b.classList.toggle('selected',b===format);b.setAttribute('aria-pressed',String(b===format));});$('#download-export').innerHTML=`${icon('export')} Export ${chosenFormat==='json'?'project':chosenFormat.toUpperCase()}`;$('#format-note').textContent=({png:'PNG captures the first frame at the full canvas resolution.',svg:'SVG preserves your vector artwork and animation. No player installation required.',gif:'GIF renders the animation in this browser. Larger or longer scenes take more time.',mp4:'MP4 uses available browser video encoding. If unsupported, the exporter explains the available alternative.',pdf:'PDF captures a high resolution raster snapshot of your composition for printing.',html:'HTML packages a standalone animated timeline player. Scene scripts are not executed in this export.',json:'The project format preserves layers, motion and scripts for future editing.'})[chosenFormat];return;}
